+  const int64_t sub_pos = sub_topk_pos[row_off + local_k];
+  const int64_t sub_total = static_cast<int64_t>(nk_large) * factor;
+  if (sub_pos < 0 || sub_pos >= sub_total) {
+    chunk_idx[row_off + local_k] = -1;
